package com.finguard.service;
import com.finguard.dao.*;import com.finguard.model.*;import com.finguard.util.*;import java.sql.*;import java.util.*;
public class TransactionService {private final TransactionDAO dao=new TransactionDAO();private final AuditLogDAO audit=new AuditLogDAO();private final RiskAnalysisService risk;public TransactionService(RiskAnalysisService r){risk=r;} public Transaction add(Transaction t)throws SQLException{InputValidator.validate(t.accountId(),t.reference(),t.amount(),t.currency(),t.type(),t.merchant(),t.timestamp());try(Connection c=DatabaseConnection.open()){c.setAutoCommit(false);try{var history=dao.byAccount(c,t.accountId());if(dao.referenceExists(c,t.reference())){audit.log(c,"DUPLICATE_REFERENCE",null,t.accountId(),"Rejected duplicate reference "+t.reference());c.commit();throw new IllegalArgumentException("Duplicate transaction reference");}var assessed=risk.evaluate(t,history);var saved=dao.insert(c,assessed);audit.log(c,"TRANSACTION_CREATED",saved.id(),saved.accountId(),"Transaction created; risk="+saved.riskLevel());if(saved.riskScore()>0){audit.log(c,"RISK_ALERT",saved.id(),saved.accountId(),String.join("; ",saved.reasons()));try(var s=c.prepareStatement("INSERT INTO risk_alerts(transaction_id,risk_score,risk_level,reasons) VALUES(?,?,?,?)")){s.setLong(1,saved.id());s.setInt(2,saved.riskScore());s.setString(3,saved.riskLevel().name());s.setString(4,String.join("; ",saved.reasons()));s.executeUpdate();}}c.commit();return saved;}catch(Exception e){if(!c.getAutoCommit())c.rollback();throw e;}}}public List<Transaction> all()throws SQLException{try(Connection c=DatabaseConnection.open()){return dao.all(c);}}public Optional<Transaction> id(long id)throws SQLException{try(Connection c=DatabaseConnection.open()){return dao.byId(c,id);}}public List<Transaction> account(String a)throws SQLException{try(Connection c=DatabaseConnection.open()){return dao.byAccount(c,a);}}public List<Transaction> range(java.time.LocalDateTime a,java.time.LocalDateTime b)throws SQLException{try(Connection c=DatabaseConnection.open()){return dao.between(c,a,b);}}public List<String> audit()throws SQLException{try(Connection c=DatabaseConnection.open()){return audit.all(c);}}public void recordEvent(String type,String message)throws SQLException{try(Connection c=DatabaseConnection.open()){audit.log(c,type,null,null,message);}}}
